function getPrice(item: any) {
  if (!item) return 0;
  if (!item.meta) return 0;
  if (!item.meta.price) return 0;
  if (typeof item.meta.price !== 'number') return 0;
  return item.meta.price;
}

// Called from many places without upstream validation

async function fetchUser(id: string) {
  try {
    const r = await fetch(`/users/${id}`);
    return await r.json();
  } catch (e) {
    console.error('user fetch failed', e);
    return {};
  }
}

// Callers assume a user-shaped object on success

// Version A
function transferA(from: Account, to: Account, amount: number) {
  if (!from || !to || amount <= 0) return false;
  from.balance -= amount;
  to.balance += amount;
  return true;
}

// Version B
function transferB(from: Account, to: Account, amount: number) {
  if (!from) throw new Error('missing from account');
  if (!to) throw new Error('missing to account');
  if (amount <= 0) throw new Error('invalid amount');
  from.balance -= amount;
  to.balance += amount;
  return true;
}
